-- UI-06 TemplateUiAssignment sample tables (PostgreSQL / init-pilot conventions)

CREATE SCHEMA IF NOT EXISTS app;

DROP TABLE IF EXISTS app."WorkTeamCapability";
DROP TABLE IF EXISTS app."WorkTeam";
DROP TABLE IF EXISTS app."WorkCapability";

CREATE TABLE app."WorkCapability"
(
    "WorkCapabilityId"        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkCapabilityGuid"      UUID NOT NULL DEFAULT gen_random_uuid(),
    "CapabilityCode"          VARCHAR(20) NOT NULL,
    "CapabilityName"          VARCHAR(200) NOT NULL,
    "CapabilityDescription"   VARCHAR(500),
    "StatusId"                INT NOT NULL DEFAULT 1,
    "RowVersion"              BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById"             BIGINT NOT NULL,
    "CreatedTime"             TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById"             BIGINT,
    "UpdatedTime"             TIMESTAMPTZ,
    "DeletedById"             BIGINT,
    "DeletedTime"             TIMESTAMPTZ,
    CONSTRAINT "UQ_WorkCapability_WorkCapabilityGuid" UNIQUE ("WorkCapabilityGuid"),
    CONSTRAINT "UQ_WorkCapability_Code" UNIQUE ("CapabilityCode"),
    CONSTRAINT "CHK_WorkCapability_Status" CHECK ("StatusId" IN (0, 1, 2))
);

CREATE TABLE app."WorkTeam"
(
    "WorkTeamId"        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkTeamGuid"      UUID NOT NULL DEFAULT gen_random_uuid(),
    "WorkTeamCode"      VARCHAR(20) NOT NULL,
    "WorkTeamName"      VARCHAR(200) NOT NULL,
    "IsEditAble"        BOOLEAN NOT NULL DEFAULT TRUE,
    "Note"              VARCHAR(500),
    "StatusId"          INT NOT NULL DEFAULT 1,
    "RowVersion"        BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById"       BIGINT NOT NULL,
    "CreatedTime"       TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById"       BIGINT,
    "UpdatedTime"       TIMESTAMPTZ,
    "DeletedById"       BIGINT,
    "DeletedTime"       TIMESTAMPTZ,
    CONSTRAINT "UQ_WorkTeam_WorkTeamGuid" UNIQUE ("WorkTeamGuid"),
    CONSTRAINT "UQ_WorkTeam_Code" UNIQUE ("WorkTeamCode"),
    CONSTRAINT "CHK_WorkTeam_Status" CHECK ("StatusId" IN (0, 1, 2))
);

CREATE TABLE app."WorkTeamCapability"
(
    "WorkTeamCapabilityId"     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkTeamCapabilityGuid"   UUID NOT NULL DEFAULT gen_random_uuid(),
    "WorkTeamId"               BIGINT NOT NULL,
    "WorkCapabilityId"         BIGINT NOT NULL,
    "IsViewAble"               BOOLEAN NOT NULL DEFAULT TRUE,
    "IsAddAble"                BOOLEAN,
    "IsEditAble"               BOOLEAN,
    "IsApproveAble"            BOOLEAN,
    "IsExportAble"             BOOLEAN,
    "StatusId"                 INT NOT NULL DEFAULT 1,
    "RowVersion"               BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById"              BIGINT NOT NULL,
    "CreatedTime"              TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById"              BIGINT,
    "UpdatedTime"              TIMESTAMPTZ,
    "DeletedById"              BIGINT,
    "DeletedTime"              TIMESTAMPTZ,
    CONSTRAINT "UQ_WorkTeamCapability_WorkTeamCapabilityGuid" UNIQUE ("WorkTeamCapabilityGuid"),
    CONSTRAINT "CHK_WorkTeamCapability_Status" CHECK ("StatusId" IN (0, 1, 2))
);

CREATE INDEX "IX_WorkTeamCapability_WorkTeamId" ON app."WorkTeamCapability" ("WorkTeamId");
CREATE INDEX "IX_WorkTeamCapability_WorkCapabilityId" ON app."WorkTeamCapability" ("WorkCapabilityId");
CREATE UNIQUE INDEX "UX_WorkTeamCapability_Team_Capability_Active"
    ON app."WorkTeamCapability" ("WorkTeamId", "WorkCapabilityId")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

INSERT INTO app."WorkCapability"
    ("CapabilityCode", "CapabilityName", "CapabilityDescription", "StatusId", "CreatedById")
VALUES
    ('LEAVE',    'Leave',        'Submit and approve employee leave', 1, 1),
    ('ATTEND',   'Attendance',   'Daily attendance and timesheet', 1, 1),
    ('PAYROLL',  'Payroll',      'Payroll run and payslip', 1, 1),
    ('OVERTIME', 'Overtime',     'Overtime request and approval', 1, 1),
    ('CLAIM',    'Claim',        'Medical and travel claims', 1, 1),
    ('RECRUIT',  'Recruitment',  'Vacancy and candidate pipeline', 1, 1),
    ('TRAINING', 'Training',     'Training catalog and enrollment', 1, 1),
    ('ASSET',    'Asset',        'Company asset assignment', 1, 1);

INSERT INTO app."WorkTeam"
    ("WorkTeamCode", "WorkTeamName", "IsEditAble", "Note", "StatusId", "CreatedById")
VALUES
    ('HR-OPS',  'HR Operations',      TRUE,  'Leave, attendance, and recruitment desk', 1, 1),
    ('FIN-DSK', 'Finance Desk',        TRUE,  'Payroll and claim processing', 1, 1),
    ('PLANT-1', 'Plant Supervisors',   FALSE, 'Shop-floor overtime and attendance only', 1, 1);

INSERT INTO app."WorkTeamCapability"
    ("WorkTeamId", "WorkCapabilityId", "IsViewAble", "IsAddAble", "IsEditAble", "IsApproveAble", "IsExportAble", "StatusId", "CreatedById")
SELECT t."WorkTeamId", c."WorkCapabilityId", v."IsViewAble", v."IsAddAble", v."IsEditAble", v."IsApproveAble", v."IsExportAble", 1, 1
FROM (VALUES
    ('HR-OPS',  'LEAVE',    TRUE, TRUE,  TRUE,  TRUE,  TRUE),
    ('HR-OPS',  'ATTEND',   TRUE, TRUE,  TRUE,  FALSE, TRUE),
    ('HR-OPS',  'RECRUIT',  TRUE, TRUE,  TRUE,  TRUE,  FALSE),
    ('FIN-DSK', 'PAYROLL',  TRUE, FALSE, TRUE,  TRUE,  TRUE),
    ('FIN-DSK', 'CLAIM',    TRUE, TRUE,  TRUE,  TRUE,  TRUE),
    ('PLANT-1', 'ATTEND',   TRUE, TRUE,  FALSE, FALSE, FALSE),
    ('PLANT-1', 'OVERTIME', TRUE, TRUE,  FALSE, TRUE,  FALSE)
) AS v("TeamCode", "CapCode", "IsViewAble", "IsAddAble", "IsEditAble", "IsApproveAble", "IsExportAble")
JOIN app."WorkTeam" t ON t."WorkTeamCode" = v."TeamCode"
JOIN app."WorkCapability" c ON c."CapabilityCode" = v."CapCode";
